    companion object {
        /** The colours of a theme in a direction. */
        fun resolve(theme: NDTheme, direction: NDDirection): NDColors = when (theme to direction) {
            NDTheme.Light to NDDirection.On -> lightOn()
            NDTheme.Dark to NDDirection.On -> darkOn()
            NDTheme.LightContrast to NDDirection.On -> lightContrastOn()
            NDTheme.DarkContrast to NDDirection.On -> darkContrastOn()
            else -> error("no colours for $theme/$direction")
        }

