/** Every dimension, in dp, for one platform and density. */
class NDMetrics private constructor(private val dp: FloatArray) {
    val space0: Float get() = dp[0]
    val space1: Float get() = dp[1]
    val space2: Float get() = dp[2]
    val space3: Float get() = dp[3]
