    val rhythm1: Float get() = dp[10]
    val rhythm2: Float get() = dp[11]
    val rhythm3: Float get() = dp[12]
    val rhythm4: Float get() = dp[13]
    val rhythm5: Float get() = dp[14]
    val rhythm10: Float get() = dp[15]
    val radiusSm: Float get() = dp[16]
    val radiusMd: Float get() = dp[17]
    val radiusLg: Float get() = dp[18]
    val radiusXl: Float get() = dp[19]
    val radius2xl: Float get() = dp[20]
    val radiusPill: Float get() = dp[21]
    val sizeIcon: Float get() = dp[22]
    val sizeIconMd: Float get() = dp[23]
    val sizeIconLg: Float get() = dp[24]
    val sizeBrand: Float get() = dp[25]
    val sizeHomeArtMax: Float get() = dp[26]
    val sizeHomeArtCenteredMax: Float get() = dp[27]
    val sizeFeaturedCardMin: Float get() = dp[28]
    val sizeDirectionCardMin: Float get() = dp[29]
    val sizeDockTile: Float get() = dp[30]
    val sizeDockIcon: Float get() = dp[31]
    val sizeDockMax: Float get() = dp[32]
    /** A 3 px pip and lane. */
    val markPip: Float get() = dp[33]
    /** The small dot and its 5 px lane: kickers, the page bar, rails. */
    val markDot: Float get() = dp[34]
    /** A 9 px node on a time line. */
    val markNode: Float get() = dp[35]
    /** The 15 px dot at a heading's, a rail's or a foot's end. */
    val markDotLg: Float get() = dp[36]
    /** The stroke of drawn controls: a menu's bars, a chevron, a disclosure's plus. */
    val markStroke: Float get() = dp[37]
    val borderWidthNone: Float get() = dp[38]
    val borderWidthThin: Float get() = dp[39]
    val borderWidthMedium: Float get() = dp[40]
    val borderWidthThick: Float get() = dp[41]
    /** Focus outline width (WCAG 2.2 2.4.13: at least a 2 px perimeter). */
    val focusWidth: Float get() = dp[42]
    /** Space between a control and its focus outline, filled with surface.base. */
    val focusGap: Float get() = dp[43]
    val sizeControlSm: Float get() = dp[44]
    val sizeControlMd: Float get() = dp[45]
    val sizeControlLg: Float get() = dp[46]
    val sizeField: Float get() = dp[47]
    val sizeTargetMin: Float get() = dp[48]

    override fun equals(other: Any?): Boolean = other is NDMetrics && dp.contentEquals(other.dp)

    override fun hashCode(): Int = dp.contentHashCode()

    companion object {
        fun resolve(platform: NDPlatform, density: NDDensity): NDMetrics = when (platform to density) {
            NDPlatform.Ios to NDDensity.Comfortable -> iosComfortable()
            NDPlatform.Ios to NDDensity.Compact -> iosCompact()
            NDPlatform.Android to NDDensity.Comfortable -> androidComfortable()
            NDPlatform.Android to NDDensity.Compact -> androidCompact()
            NDPlatform.Desktop to NDDensity.Comfortable -> desktopComfortable()
            NDPlatform.Desktop to NDDensity.Compact -> desktopCompact()
            else -> error("no metrics for $platform/$density")
        }

