/** Numbers: opacity, leading, tracking (em), stacking, springs. */
object NDNumbers {
    /** A disabled control (WCAG exempts it from contrast). */
    const val opacityDisabled: Float = 0.4f
    const val opacityMuted: Float = 0.6f
    const val opacitySubtle: Float = 0.16f
    /** Scrim behind a dialog. */
    const val opacityOverlay: Float = 0.55f
    const val textLeadingDisplay: Float = 1.06f
    const val textLeadingH1: Float = 1.1f
    const val textLeadingH2: Float = 1.15f
    const val textLeadingH3: Float = 1.22f
    const val textLeadingH4: Float = 1.3f
    const val textLeadingBodyLg: Float = 1.55f
    const val textLeadingBody: Float = 1.6f
    const val textLeadingLabel: Float = 1.4f
    const val textLeadingCaption: Float = 1.3f
    const val scriptLeadingAr: Float = 1.8f
    const val scriptLeadingZh: Float = 1.75f
    /** Display headings. */
    const val trackingTight: Float = -0.02f // em
    const val trackingSnug: Float = -0.01f // em
    const val trackingNormal: Float = 0.0f // em
    const val trackingLoose: Float = 0.02f // em
    const val trackingWide: Float = 0.04f // em
    /** Upper-case labels and kickers. */
    const val trackingWider: Float = 0.06f // em
    const val springStandardStiffness: Float = 380.0f
    const val springStandardDampingRatio: Float = 0.8f
    const val springGentleStiffness: Float = 200.0f
    const val springGentleDampingRatio: Float = 1.0f
    const val springSnappyStiffness: Float = 700.0f
    const val springSnappyDampingRatio: Float = 0.9f
    const val zBase: Float = 0.0f
    const val zRaised: Float = 10.0f
    const val zSticky: Float = 100.0f
    const val zOverlay: Float = 200.0f
    const val zDialog: Float = 300.0f
    const val zToast: Float = 400.0f
    const val zSkip: Float = 1000.0f
    const val artGlow: Float = 0.4f
}

/** Font weights (1..1000). */
object NDWeights {
    const val weightRegular: Int = 400
    const val weightMedium: Int = 500
    const val weightSemibold: Int = 600
}

/** Font families per platform, most preferred first. */
object NDFonts {
    fun stack(family: NDFontFamily, platform: NDPlatform): List<String> = when (family to platform) {
        NDFontFamily.Sans to NDPlatform.Ios -> listOf("IBM Plex Sans", ".AppleSystemUIFont")
        NDFontFamily.Sans to NDPlatform.Android -> listOf("IBM Plex Sans", "Roboto")
        NDFontFamily.Sans to NDPlatform.Desktop -> listOf("IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "-apple-system", "Segoe UI", "Roboto", "Helvetica Neue", "Arial", "sans-serif")
        NDFontFamily.SansAr to NDPlatform.Ios -> listOf("IBM Plex Sans Arabic", ".AppleSystemUIFont")
        NDFontFamily.SansAr to NDPlatform.Android -> listOf("IBM Plex Sans Arabic", "Noto Sans Arabic")
        NDFontFamily.SansAr to NDPlatform.Desktop -> listOf("IBM Plex Sans Arabic", "IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "Segoe UI", "Tahoma", "Arial", "sans-serif")
        NDFontFamily.SansZh to NDPlatform.Ios -> listOf("PingFang SC")
        NDFontFamily.SansZh to NDPlatform.Android -> listOf("Noto Sans CJK SC")
        NDFontFamily.SansZh to NDPlatform.Desktop -> listOf("IBM Plex Sans", "Noto Sans SC", "IBM Plex Sans Fallback", "system-ui", "PingFang SC", "Microsoft YaHei", "sans-serif")
        NDFontFamily.Mono to NDPlatform.Ios -> listOf("SF Mono", "Menlo")
        NDFontFamily.Mono to NDPlatform.Android -> listOf("monospace")
        NDFontFamily.Mono to NDPlatform.Desktop -> listOf("ui-monospace", "SFMono-Regular", "Menlo", "Consolas", "Liberation Mono", "monospace")
        else -> error("no fonts for $family/$platform")
    }
}

/** Durations in milliseconds. */
object NDDurations {
    fun durationUiFast(motion: NDMotion): Long = when (motion) {
        NDMotion.Standard -> 150L
        NDMotion.Reduced -> 0L
    }
    fun durationUi(motion: NDMotion): Long = when (motion) {
        NDMotion.Standard -> 250L
        NDMotion.Reduced -> 0L
    }
    fun durationScene(motion: NDMotion): Long = when (motion) {
        NDMotion.Standard -> 450L
        NDMotion.Reduced -> 0L
    }
    fun durationSceneSlow(motion: NDMotion): Long = when (motion) {
        NDMotion.Standard -> 900L
        NDMotion.Reduced -> 0L
    }
}

/** A cubic Bezier easing: control points (x1, y1, x2, y2). */
data class NDEasing(val x1: Float, val y1: Float, val x2: Float, val y2: Float)

object NDEasings {
    /** The standard easing of interface motion. */
    val easing = NDEasing(0.2f, 0.7f, 0.2f, 1.0f)
    /** Decelerate: something arriving. */
    val easingEnter = NDEasing(0.0f, 0.0f, 0.2f, 1.0f)
    /** Accelerate: something leaving. */
    val easingExit = NDEasing(0.4f, 0.0f, 1.0f, 1.0f)
    /** A larger, more noticeable change. */
    val easingEmphasized = NDEasing(0.2f, 0.0f, 0.0f, 1.0f)
}

/** One layer of a shadow, in dp. */
data class NDShadowLayer(
    val color: NDColor,
    val x: Float,
    val y: Float,
    val blur: Float,
    val spread: Float,
    val inset: Boolean,
)

object NDShadows {
    fun elevation1(theme: NDTheme): List<NDShadowLayer> = when (theme) {
        NDTheme.Light -> listOf(NDShadowLayer(NDColor(0x1F000000.toInt()), 0.0f, 1.0f, 3.0f, 0.0f, false))
        NDTheme.Dark -> listOf(NDShadowLayer(NDColor(0x99000000.toInt()), 0.0f, 1.0f, 2.0f, 0.0f, false))
        NDTheme.LightContrast -> listOf(NDShadowLayer(NDColor(0x1F000000.toInt()), 0.0f, 1.0f, 3.0f, 0.0f, false))
        NDTheme.DarkContrast -> listOf(NDShadowLayer(NDColor(0x99000000.toInt()), 0.0f, 1.0f, 2.0f, 0.0f, false))
    }
    fun elevation2(theme: NDTheme): List<NDShadowLayer> = when (theme) {
        NDTheme.Light -> listOf(NDShadowLayer(NDColor(0x1F000000.toInt()), 0.0f, 6.0f, 16.0f, 0.0f, false))
        NDTheme.Dark -> listOf(NDShadowLayer(NDColor(0xB3000000.toInt()), 0.0f, 4.0f, 12.0f, 0.0f, false))
        NDTheme.LightContrast -> listOf(NDShadowLayer(NDColor(0x1F000000.toInt()), 0.0f, 6.0f, 16.0f, 0.0f, false))
        NDTheme.DarkContrast -> listOf(NDShadowLayer(NDColor(0xB3000000.toInt()), 0.0f, 4.0f, 12.0f, 0.0f, false))
    }
    fun elevation3(theme: NDTheme): List<NDShadowLayer> = when (theme) {
        NDTheme.Light -> listOf(NDShadowLayer(NDColor(0x29000000.toInt()), 0.0f, 16.0f, 40.0f, 0.0f, false))
        NDTheme.Dark -> listOf(NDShadowLayer(NDColor(0xCC000000.toInt()), 0.0f, 12.0f, 32.0f, 0.0f, false))
        NDTheme.LightContrast -> listOf(NDShadowLayer(NDColor(0x29000000.toInt()), 0.0f, 16.0f, 40.0f, 0.0f, false))
        NDTheme.DarkContrast -> listOf(NDShadowLayer(NDColor(0xCC000000.toInt()), 0.0f, 12.0f, 32.0f, 0.0f, false))
    }
}

/**
 * A text style on a platform: family, size (sp), line height as a multiple of the size, weight,
 * letter spacing as a share of the size (em), case, and the Material 3 role it fills.
 */
data class NDTextStyle(
    val family: NDFontFamily,
    val size: Float,
    val lineHeight: Float,
    val weight: Int,
    val tracking: Float,
    val uppercase: Boolean,
    val material: String?,
) {
    companion object {
        /** The style of a role on a platform, adjusted for the script of the text. */
        fun resolve(role: NDTypeRole, platform: NDPlatform, script: NDScript = NDScript.Latin): NDTextStyle {
            val base = base(role, platform)
            return base.copy(
                family = if (base.family == NDFontFamily.Sans) script.family else base.family,
                lineHeight = if (role.isBody) script.bodyLeading ?: base.lineHeight else base.lineHeight,
                tracking = if (script.tracksLetters) base.tracking else 0f,
                uppercase = script.hasCase && base.uppercase,
            )
        }

        private fun base(role: NDTypeRole, platform: NDPlatform): NDTextStyle = when (role to platform) {
            NDTypeRole.Display to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 34.0f, 1.06f, 400, -0.02f, false, "displaySmall")
            NDTypeRole.Display to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 36.0f, 1.06f, 400, -0.02f, false, "displaySmall")
            NDTypeRole.Display to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 40.0f, 1.06f, 400, -0.02f, false, "displaySmall")
            NDTypeRole.H1 to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 28.0f, 1.1f, 400, -0.01f, false, "headlineLarge")
            NDTypeRole.H1 to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 32.0f, 1.1f, 400, -0.01f, false, "headlineLarge")
            NDTypeRole.H1 to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 32.0f, 1.1f, 400, -0.01f, false, "headlineLarge")
            NDTypeRole.H2 to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 22.0f, 1.15f, 400, -0.01f, false, "headlineMedium")
            NDTypeRole.H2 to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 28.0f, 1.15f, 400, -0.01f, false, "headlineMedium")
            NDTypeRole.H2 to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 28.0f, 1.15f, 400, -0.01f, false, "headlineMedium")
            NDTypeRole.H3 to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 20.0f, 1.22f, 400, -0.01f, false, "headlineSmall")
            NDTypeRole.H3 to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 24.0f, 1.22f, 400, -0.01f, false, "headlineSmall")
            NDTypeRole.H3 to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 22.0f, 1.22f, 400, -0.01f, false, "headlineSmall")
            NDTypeRole.H4 to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 17.0f, 1.3f, 400, -0.01f, false, "titleLarge")
            NDTypeRole.H4 to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 22.0f, 1.3f, 400, -0.01f, false, "titleLarge")
            NDTypeRole.H4 to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 18.0f, 1.3f, 400, -0.01f, false, "titleLarge")
            NDTypeRole.Lead to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 17.0f, 1.55f, 400, 0.0f, false, "bodyLarge")
            NDTypeRole.Lead to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 16.0f, 1.55f, 400, 0.0f, false, "bodyLarge")
            NDTypeRole.Lead to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 16.0f, 1.55f, 400, 0.0f, false, "bodyLarge")
            NDTypeRole.Body to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 16.0f, 1.6f, 400, 0.0f, false, "bodyMedium")
            NDTypeRole.Body to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 14.0f, 1.6f, 400, 0.0f, false, "bodyMedium")
            NDTypeRole.Body to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 14.0f, 1.6f, 400, 0.0f, false, "bodyMedium")
            NDTypeRole.Label to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 15.0f, 1.4f, 400, 0.0f, false, "labelLarge")
            NDTypeRole.Label to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 14.0f, 1.4f, 400, 0.0f, false, "labelLarge")
            NDTypeRole.Label to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 13.0f, 1.4f, 400, 0.0f, false, "labelLarge")
            NDTypeRole.Kicker to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 15.0f, 1.4f, 400, 0.06f, true, "labelLarge")
            NDTypeRole.Kicker to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 14.0f, 1.4f, 400, 0.06f, true, "labelLarge")
            NDTypeRole.Kicker to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 13.0f, 1.4f, 400, 0.06f, true, "labelLarge")
            NDTypeRole.Caption to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Sans, 12.0f, 1.3f, 400, 0.0f, false, "bodySmall")
            NDTypeRole.Caption to NDPlatform.Android -> NDTextStyle(NDFontFamily.Sans, 12.0f, 1.3f, 400, 0.0f, false, "bodySmall")
            NDTypeRole.Caption to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Sans, 12.0f, 1.3f, 400, 0.0f, false, "bodySmall")
            NDTypeRole.Code to NDPlatform.Ios -> NDTextStyle(NDFontFamily.Mono, 15.2f, 1.6f, 400, 0.0f, false, "bodyMedium")
            NDTypeRole.Code to NDPlatform.Android -> NDTextStyle(NDFontFamily.Mono, 13.3f, 1.6f, 400, 0.0f, false, "bodyMedium")
            NDTypeRole.Code to NDPlatform.Desktop -> NDTextStyle(NDFontFamily.Mono, 13.3f, 1.6f, 400, 0.0f, false, "bodyMedium")
            else -> error("no style for $role/$platform")
        }
    }
}
